/* Slovník pojmů. k = klíč (slug), t = název, alt = cizojazyčný ekvivalent, d = definice (HTML),
   see = okruhy k odkazu, pokud pojem nemá přímý výskyt v textu. */
window.HK_GLOSSARY = [
{k:'aggravace',t:'aggravace',alt:'aggravatio, homeopatické zhoršení',d:'Přechodné zhoršení stávajících symptomů krátce po podání léku (hodiny až 2–3 dny), po němž následuje zlepšení. Nauka je vysvětluje jako reakci organismu na „umělou nemoc“ vyvolanou lékem. <b>Rozhodující rozlišení:</b> aggravace je krátká, zhoršuje jen <em>stávající</em> symptomy a celkový stav i energie při ní zůstávají dobré. Zhoršení, které postupuje, přidává nové projevy a snižuje energii, není aggravace, nýbrž zhoršení nemoci. Zhoršení ohrožující funkci orgánu nebo život není aggravace nikdy.'},
{k:'ajurveda',t:'ájurvéda',alt:'āyurveda',d:'Tradiční indický léčebný systém pracující s rovnováhou tří <i>dóš</i> (váta, pitta, kapha), se stavem trávicí síly (<i>agni</i>) a s hromaděním toxinů (<i>áma</i>). Léčba volí <b>opačný princip</b> (chladné na horké) podle konstitučního typu; používá bylinné a minerální směsi v hmotných dávkách, očistné procedury (pančakarma), dietu a jógu. Na rozdíl od homeopatie nevychází z provingem zjištěné podobnosti a nepracuje s potenciací. U části přípravků je doložena kontaminace olovem, rtutí a arzenem.'},
{k:'akutni-pripad',t:'akutní případ',alt:'acute case',d:'Náhle vzniklý stav s jasným začátkem a s tendencí ke spontánnímu ukončení. V homeopatii se odebírá rychleji, s méně symptomy, ale ostřejšími; rozhodují rychlost nástupu, příčina, modality, chování v nemoci a žízeň. Duševní symptomy se hodnotí jen jako <em>změna</em> proti obvyklému stavu. Lék se podává častěji (typicky C30 každou 1–4 hodiny) a vysazuje se při prvním jasném zlepšení. Vždy předchází bezpečnostní triáž.'},
{k:'alokacni-utajeni',t:'alokační utajení',alt:'allocation concealment',d:'Opatření, které zabraňuje tomu, aby osoba zařazující pacienta do studie předem věděla, do které skupiny pacient přijde (centrální randomizace, zapečetěné neprůhledné obálky, nezávislá lékárna). Není totožné se <a href="#gl-zaslepeni">zaslepením</a>: působí <em>při</em> zařazení, nikoli po něm. Metodologické studie ukazují, že nedostatečné alokační utajení nadhodnocuje výsledky silněji než absence zaslepení — je to nejvíc podceňovaný ukazatel kvality studie.'},
{k:'alopatie',t:'alopatie',alt:'allopathia',d:'Hahnemannův polemický název pro medicínu, která podle něj léčí nesouvisejícími prostředky, tedy „jinak“ (řec. <i>állos</i> — jiný). Dnes se slovo užívá jako označení konvenční medicíny, byť s hodnotícím podtónem, kterému je v odborné komunikaci lepší se vyhnout; neutrální termín je „konvenční“ nebo „standardní medicína“.'},
{k:'alostaze',t:'alostáze',alt:'allostasis',d:'Schopnost organismu měnit své regulační nastavení podle nároků prostředí — tedy udržovat stabilitu <em>změnou</em>, nikoli jen návratem k výchozí hodnotě. Dlouhodobá zátěž vede k „alostatické zátěži“ (opotřebení regulačních systémů) s měřitelnými ukazateli. Pojem se v moderní literatuře nabízí jako reinterpretace <a href="#gl-vitalni-sila">vitální síly</a>; taková reinterpretace je užitečná, ale mění význam Hahnemannova tvrzení a neřeší otázku mechanismu.'},
{k:'anamneza',t:'anamnéza (odběr případu)',alt:'case taking',d:'Systematické zjišťování všech informací potřebných k volbě léku. Homeopatická anamnéza se od lékařské liší cílem: hledá to, co je na pacientovi <em>neobvyklé</em>, pracuje s celou osobou (spánek, jídlo, teplo a chlad, prožívání, biografie) a zaznamenává doslova pacientova vlastní slova. Vede se ve třech fázích — spontánní vyprávění, upřesňování, cílené doplnění (§ 84–99).'},
{k:'antroposoficka-medicina',t:'antroposofická medicína',alt:'anthroposophic medicine',d:'Léčebný systém založený Rudolfem Steinerem a Itou Wegman (1920). Používá potencované i hmotné přípravky, ale volí je podle <b>typologické a kosmologické analogie</b> (vztah orgán–rostlina–kov–planeta), nikoli podle provingem zjištěné podobnosti symptomů. Připouští kombinace a má vlastní léčebné formy (rytmické injekce, eurytmie, výtvarná terapie, preparáty jmelí v onkologii). Samostatný systém, ne odnož homeopatie.'},
{k:'avogadro',t:'Avogadrova konstanta',alt:'N<sub>A</sub>',d:'Počet částic v jednom molu látky, přibližně 6,022 × 10<sup>23</sup>. Z ní plyne <b>Avogadrova mez</b>: okolo potence 12C (ředění 10<sup>−24</sup>) se vyčerpává pravděpodobnost, že v dávce zůstane jediná molekula výchozí látky. Potence 30C (10<sup>−60</sup>), 200C nebo 1M jsou o desítky až tisíce řádů za touto hranicí. Adept nesmí tvrdit, že v 30C je ještě molekula účinné látky — je to věcně nesprávné.'},
{k:'centralni-senzace',t:'centrální senzace',alt:'central sensation, vital sensation',d:'Pojem Rajana Sankarana: základní způsob, jakým pacient prožívá svět a který se podle něj opakuje ve všech jeho symptomech (například „jsem pronásledován a musím uniknout“). Léky se pak řadí podle společné senzace do říší a rostlinných čeledí. Metodické riziko: přechod od <em>pozorovaného symptomu</em> k <em>interpretované senzaci</em> zvyšuje podíl výkladu, a tím i riziko projekce terapeuta.'},
{k:'cervene-vlajky',t:'červené vlajky',alt:'red flags',d:'Varovná znamení, při nichž pacient patří do akutní či specializované péče bez ohledu na jakoukoli homeopatickou úvahu — porucha vědomí, náhlá neurologická porucha, dušnost v klidu, svíravá bolest na hrudi, vyrážka nemizící při tlaku, horečka u kojence do 3 měsíců, náhlá břišní příhoda, krvácení do trávicího traktu, známky šoku, suicidální plán, krvácení v graviditě, nevysvětlené hubnutí a další. Kontrolují se <b>před</b> volbou léku, nikoli po ní.'},
{k:'charakteristicky-symptom',t:'charakteristický symptom',alt:'characteristic symptom',d:'Symptom, který individualizuje <em>tohoto</em> pacienta, tedy odlišuje ho od jiných pacientů se stejnou diagnózou. Protiklad <a href="#gl-spolecny-symptom">společného symptomu</a>. Provozní test: kdybych symptom z případu vypustil, změnil by se seznam kandidátních léků? Jestliže ne, není charakteristický.'},
{k:'chilly-hot',t:'zimomřivý / horkokrevný pacient',alt:'chilly / hot patient',d:'Základní termoregulační rozdělení pacientů, které je nejsilnějším jednotlivým <a href="#gl-generalia">generálním symptomem</a>: zimomřivý pacient (<i>chilly</i>) potřebuje teplo, přikrývky, nesnáší chlad a průvan (<span class="rx">Silicea</span>, <span class="rx">Psorinum</span>, <span class="rx">Calcarea carbonica</span>); horkokrevný (<i>hot</i>) nesnáší teplo a dusno, odkopává peřinu, potřebuje čerstvý vzduch (<span class="rx">Sulphur</span>, <span class="rx">Pulsatilla</span>, <span class="rx">Iodum</span>). Rozděluje Materii mediku vpůli a má velkou eliminační sílu.'},
{k:'chronicky-pripad',t:'chronický případ',alt:'chronic case',d:'Dlouhodobý stav bez tendence ke spontánnímu ukončení, u něhož nauka předpokládá <a href="#gl-miasma">miasmatické</a> pozadí. Odběr trvá 60–120 minut a zaměřuje se na dlouhodobé vzorce: generalia, duševní úroveň, biografii, rodinnou anamnézu, časovou osu. Hodnocení probíhá v týdnech až měsících; sleduje se trend, nikoli jednotlivé dny.'},
{k:'druhy-predpis',t:'druhý předpis',alt:'second prescription',d:'Rozhodnutí, co podat po prvním léku. Kent ho považoval za obtížnější než první předpis, protože zde nerozhoduje jen totalita, ale i <em>reakce na první lék</em>. Možnosti: tentýž lék v téže potenci (relaps), tentýž lék ve vyšší či nižší potenci, <a href="#gl-komplementarni-leky">komplementární lék</a>, zcela jiný lék, <a href="#gl-intercurrentni-lek">intercurrentní nozod</a>, nebo — zcela legitimně — <b>žádný lék</b>, pokud zlepšení probíhá.'},
{k:'dynamizace',t:'dynamizace',alt:'dynamisatio',d:'Alternativní název pro <a href="#gl-potenciace">potenciaci</a>, který zdůrazňuje, že podle nauky nerozhoduje samo ředění, nýbrž mechanický vklad energie — <a href="#gl-sukuse">sukuse</a> u tekutin a <a href="#gl-triturace">triturace</a> u nerozpustných látek. Hahnemann v § 269 mluví o „rozvíjení dynamických léčivých sil“. Tvrzení o odlišnosti potencovaného a jen naředěného přípravku je testovatelné; reprodukovaný doklad rozdílu chybí.'},
{k:'easac',t:'EASAC',alt:'European Academies&#39; Science Advisory Council',d:'Poradní sbor vědeckých akademií členských zemí EU. Ve stanovisku z roku 2017 uvedl, že tvrzení o účinnosti homeopatie nejsou vědecky podložena, a doporučil nehradit ji z veřejných prostředků, uvádět na obalech absenci důkazu účinnosti a regulovat reklamu. Jde o odborné stanovisko, nikoli regulatorní akt — politicky i odborně však velmi vlivné.'},
{k:'ech',t:'ECH',alt:'European Committee for Homeopathy',d:'Evropská zastřešující organizace lékařů-homeopatů, která formuluje vzdělávací standardy, rámec zkoušek pro profesní a lékařský diplom a metodické pokyny (například guidelines pro <a href="#gl-proving">provingy</a>). Profesní diplom v rámci ECH se týká <b>klasické, unicistické a individualizované</b> homeopatie, nikoli komplexních přípravků.'},
{k:'eliminacni-rubrika',t:'eliminační rubrika',alt:'eliminating rubric',d:'Rubrika zvolená z jednoho jistého symptomu s vysokou rozlišovací silou, podle níž se z analýzy <b>vyřadí všechny léky, které ji neobsahují</b> — bez ohledu na jejich skóre v ostatních rubrikách. Nejsilnější a zároveň nejnebezpečnější nástroj repertorizace: při chybném výběru se správný lék ztratí nenávratně. Používat jen u symptomu gradace 3, spontánně uvedeného, a raději v širší než v nejužší rubrice.'},
{k:'externi-validita',t:'externí validita',alt:'external validity, generalisability',d:'Míra, v níž lze výsledky studie přenést do reálné praxe. Obor namítá, že studie s fixním lékem má nízkou externí validitu pro individualizovanou homeopatii — námitka je legitimní, ale řešitelná designem (individualizovaný předpis s randomizací přípravek/placebo, <a href="#gl-n-of-1">N-of-1</a>). Externí validitu je třeba odlišit od <b>interní validity</b> (zda studie měří to, co tvrdí, bez zkreslení).'},
{k:'funnel-plot',t:'funnel plot',alt:'graf asymetrie',d:'Graf v meta-analýze, který zobrazuje efekt jednotlivých studií proti jejich velikosti či přesnosti. Symetrický „trychtýř“ svědčí o nepřítomnosti <a href="#gl-publikacni-zkresleni">publikačního zkreslení</a>; asymetrie naznačuje, že malé studie s negativním výsledkem chybí, nebo že malé studie systematicky nadhodnocují efekt. Tento nástroj použil Shang a kol. (2005) při analýze homeopatických studií.'},
{k:'generalia',t:'generalia (celkové symptomy)',alt:'general symptoms',d:'Symptomy vztahující se k celému člověku, nikoli k jednomu orgánu. Jazykový test je spolehlivý: <b>lze je vyjádřit s podmětem „já“</b> — „je mi zima“, „jsem horší ve vlhku“, „mám žízeň na led“. Patří sem termoregulace, reakce na počasí, denní rytmus energie, žízeň, chutě a averze, spánek, pocení, reakce na tlak a polohu, cyklické zhoršení. V hierarchii stojí hned za duševními symptomy a mají velkou eliminační sílu. <b>Nezaměňovat</b> se <a href="#gl-spolecny-symptom">společným symptomem</a>, který má nulovou váhu.'},
{k:'generalizace',t:'generalizace',alt:'generalisation (Bönninghausen)',d:'Bönninghausenův princip: modalita zjištěná u jednoho konkrétního symptomu se považuje za vlastnost pacienta jako celku a hledá se v obecných (generálních) rubrikách. Například „bolest kolena je lepší teplem“ → <i>Generals — warmth, ameliorated</i>. Je to nástroj, který umožňuje pracovat i s případy chudými na symptomy; podmínkou je <b>ověřit otázkou</b>, že modalita platí i mimo dané místo, jinak jde o neoprávněnou generalizaci.'},
{k:'genus-epidemicus',t:'genus epidemicus',alt:'lék epidemie',d:'Postup podle § 100–104: při epidemii se pečlivě odeberou první případy (obvykle 5–10), z nich se sestaví souhrnný obraz epidemie a určí lék odpovídající tomuto <em>kolektivnímu</em> obrazu; ten se pak podává dalším nemocným. Je to nástroj <b>léčby nemocných</b>, nikoli prevence u zdravých — rozšíření na „homeopatickou <a href="#gl-profylaxe">profylaxi</a>“ překračuje Organon i evidenci. Historické příklady: <span class="rx">Camphora</span> a <span class="rx">Veratrum</span> (cholera 1831), <span class="rx">Belladonna</span> (skarlatina).'},
{k:'globuli',t:'granule (globuli)',alt:'globuli',d:'Nejběžnější homeopatická léková forma: sacharózovo-laktózové kuličky napuštěné potencovaným roztokem. Velikosti se značí číslem; nejmenší („poppy-seed“, velikost makového zrna) se používají pro <a href="#gl-lm-potence">LM potence</a>. Podávají se pod jazyk, tradičně mimo jídlo a bez dotyku rukou. Lze je rozpustit ve vodě a podávat po lžičkách, což umožňuje titraci dávky.'},
{k:'gradace-leku',t:'gradace léku v rubrice',alt:'remedy grade',d:'Vyznačení váhy léku v rubrice repertoria. U Kenta typograficky: VELKÁ PÍSMENA = 3, <i>kurzíva</i> = 2, obyčejné písmo = 1; moderní syntézy užívají i stupeň 4. <b>Co gradace znamená:</b> redakční hodnocení spolehlivosti a četnosti výskytu symptomu ve zdrojích. <b>Co neznamená:</b> intenzitu symptomu u pacienta ani pravděpodobnost, že lék pomůže. Hodnoty z různých repertorií nejsou vzájemně srovnatelné.'},
{k:'gradace-symptomu',t:'gradace symptomu',alt:'symptom intensity 0–3',d:'Ohodnocení intenzity a jistoty symptomu u pacienta: <b>3</b> = intenzivní, trvalý či častý, spontánně uvedený, ovlivňuje život; <b>2</b> = jasně přítomný, uvedený po doptání; <b>1</b> = slabý, nejistý; <b>0</b> = nepotvrzený, společný, patognomický nebo vzniklý sugestivní otázkou. Vstupuje do <a href="#gl-repertorizacni-mrizka">mřížky</a> jako váha symptomu. Spontánně uvedený symptom má vždy vyšší hodnotu než tentýž symptom vyvolaný otázkou.'},
{k:'grade',t:'GRADE',alt:'Grading of Recommendations Assessment, Development and Evaluation',d:'Standardizovaný systém hodnocení <b>jistoty evidence</b> (vysoká, střední, nízká, velmi nízká) a síly doporučení. Bere v úvahu riziko zkreslení, nekonzistenci, nepřímost, nepřesnost a publikační zkreslení. Při čtení přehledu je uvedení hodnocení GRADE známkou kvality; jeho absence znamená, že si čtenář musí jistotu evidence posoudit sám.'},
{k:'hab',t:'HAB',alt:'Homöopathisches Arzneibuch',d:'Německý homeopatický lékopis, de facto referenční v evropském prostoru. Obsahuje předpisy (<i>Vorschriften</i>) pro přípravu matečných tinktur podle typu a vlhkosti drogy, postupy triturace a potenciace, požadavky na nosiče a lékové formy a zvláštní režim pro nozody. Vedle něj platí <b>Evropský lékopis</b> (Ph. Eur.) s obecnými monografiemi a v USA <b>HPUS</b>.'},
{k:'heringova-pravidla',t:'Heringova pravidla',alt:'Hering&#39;s law, direction of cure',d:'Soubor pozorování o směru uzdravování, tradičně přisuzovaný Constantinu Heringovi (sám takový seznam nesepsal — dnešní čtyřbodová podoba je pozdější syntéza z Hahnemannových poznámek, § 161, 225, 253). Uzdravování postupuje: <b>1.</b> zevnitř navenek, <b>2.</b> zhora dolů, <b>3.</b> od vitálně důležitějších orgánů k méně důležitým, <b>4.</b> v obráceném pořadí, než symptomy vznikly (návrat starých symptomů). <b>Nadřazené kritérium:</b> celkový stav a energie pacienta.'},
{k:'heroicka-medicina',t:'heroická medicína',alt:'heroic medicine',d:'Standardní terapie konce 18. a začátku 19. století: opakované puštění žilou až do mdlob, vysoké dávky projímadel a dávidel, kalomel (chlorid rtuťný) do stadia salivace, vezikatorie, baňkování. Právě proti ní Hahnemannův systém vznikl. Historicky vysvětluje raný klinický úspěch homeopatie: předčila tehdejší standard nikoli tím, co dělala, nýbrž tím, co <em>nedělala</em>.'},
{k:'hierarchie-symptomu',t:'hierarchie symptomů',alt:'hierarchy of symptoms',d:'Pravidlo, že symptomy nemají stejnou váhu. Kentova trojstupňová hierarchie: <b>1.</b> duševní a emoční (vnitřně: vůle a cit &gt; rozum a bludy &gt; paměť), <b>2.</b> generální (celkové), <b>3.</b> partikulární (místní). <b>Dvě výjimky, které ji přebíjejí:</b> silný <a href="#gl-srp">SRP</a> symptom váží více než obecný duševní symptom; a modalizovaný partikulární symptom váží mnohem více než nemodalizovaný. Sjednocující princip: hledá se symptom s největší rozlišovací (eliminační) silou.'},
{k:'homeopatie',t:'homeopatie',alt:'homoeopathia — z řec. hómoios (podobný) + páthos (utrpení)',d:'Terapeutický systém založený Samuelem Hahnemannem roku 1796. Lék se volí podle <a href="#gl-zakon-podobnosti">zákona podobnosti</a>: podává se látka, která u zdravého vyvolává symptomy nejpodobnější symptomům nemocného. Léky se připravují ředěním a <a href="#gl-potenciace">potenciací</a>, volí se individuálně podle <a href="#gl-totalita-symptomu">totality symptomů</a> a v klasické praxi se podává jediný lék v jednom čase. Specifická účinnost nad rámec placeba není podle převažujícího vědeckého stanoviska prokázána.'},
{k:'hormeze',t:'hormeze',alt:'hormesis',d:'Bifázická odpověď na dávku: látka, která ve vysoké dávce škodí, může v nízké dávce vyvolat stimulační či adaptivní odpověď (ionizující záření, některé toxiny, fyzická zátěž). Bývá uváděna jako „vědecký základ homeopatie“ — <b>nadsazeně</b>: hormeze funguje v dávkovém rozmezí, kde je látka prokazatelně přítomna, a její efekty jsou nespecifické (aktivace obecných reparačních mechanismů), zatímco homeopatie tvrdí specificitu podle symptomové podobnosti.'},
{k:'individualizace',t:'individualizace',alt:'individualisation',d:'Zásada, že lék se volí podle <a href="#gl-totalita-symptomu">totality symptomů</a> konkrétního člověka, nikoli podle diagnózy (§ 18). Dva pacienti se stejnou diagnózou dostanou různý lék, pokud se liší jejich modality, senzace, duševní stav či příčina. Individualizace je také důvodem, proč klasická RCT s fixním lékem netestuje homeopatickou praxi — a proč jsou meta-analýzy individualizované léčby relevantnější.'},
{k:'informovany-souhlas',t:'informovaný souhlas',alt:'informed consent',d:'Proces (ne podpis), jímž pacient před léčbou dostane pravdivé informace a rozhodne se. U homeopatie musí obsahovat: co metoda je, <b>jaké je postavení její evidence</b> (nikoli „je to prokázané“), co léčba obnáší, kolik bude stát, jak dlouho potrvá, a že <b>nenahrazuje indikovanou konvenční léčbu</b>. Souhlas se zaznamenává. Zamlčení nepříznivé evidence činí souhlas neinformovaným.'},
{k:'inimicky-lek',t:'inimické léky',alt:'inimical remedies',d:'Léky, které se podle klinické tradice „nesnášejí“ a nemají se podávat krátce po sobě, protože reakce bývá nepříznivá — například <span class="rx">Apis</span> a <span class="rx">Rhus toxicodendron</span>, <span class="rx">Causticum</span> a <span class="rx">Phosphorus</span>, <span class="rx">Silicea</span> a <span class="rx">Mercurius</span>. Seznamy jsou mezi zdroji nekonzistentní a jejich původ obvykle nedohledatelný; u vysokých potencí nelze mluvit o farmakologické interakci. Používat jako heuristiku, ne jako pravidlo přebíjející totalitu.'},
{k:'integrativni-medicina',t:'integrativní medicína',alt:'integrative medicine',d:'Koordinovaná péče kombinující konvenční medicínu s doplňkovými postupy tam, kde pro to existuje důvod a kde je to bezpečné — s jedním plánem, komunikací mezi poskytovateli, definovanými rolemi a hodnocením přínosu. <b>Není</b> eklektismus („zkusíme všechno“). Odlišit od <a href="#gl-komplementarni-medicina">komplementární</a> (vedle konvenční léčby) a alternativní (místo ní) medicíny.'},
{k:'intercurrentni-lek',t:'intercurrentní lék',alt:'intercurrent remedy',d:'Lék vložený do probíhající léčby, obvykle <a href="#gl-nozod">nozod</a> odpovídající miasmatickému pozadí, když léčba dobře zvoleným lékem stagnuje. Po jeho podání se obvykle vrací k původnímu léku. Pozor na pořadí: při stagnaci se nejprve hledají <a href="#gl-prekazky-vyleceni">překážky uzdravení</a>, teprve potom se zvažuje intercurrentní podání.'},
{k:'itt',t:'analýza podle původního zařazení (ITT)',alt:'intention-to-treat analysis',d:'Způsob analýzy studie, kdy se každý pacient hodnotí ve skupině, do níž byl <b>původně randomizován</b> — i když léčbu nedokončil nebo ji změnil. Zachovává výhodu randomizace a je konzervativnější. Protikladem je analýza „per protocol“ (jen dokončivší), která systematicky <b>nadhodnocuje</b> efekt, protože vyřazuje pacienty, u nichž léčba nefungovala nebo ji nesnesli.'},
{k:'izopatie',t:'izopatie',alt:'isopathia',d:'Podávání potencované <b>téže</b> látky, která nemoc vyvolala (pyl při senné rýmě, kravské mléko při nesnášenlivosti). Není totožná s homeopatií, která vychází z podobnosti symptomů, ne z identity látky, a ani s vakcinací, která používá měřitelnou dávku imunogenu a má doložený imunologický mechanismus. Do izopatie svým způsobem patří i použití <a href="#gl-nozod">nozodů</a> podle příčiny.'},
{k:'jedna-medicina',t:'jedna medicína',alt:'one medicine',d:'Teze, že dělení na „konvenční“ a „alternativní“ medicínu je historické, nikoli věcné: existuje jedna medicína a jedno kritérium pro všechny postupy — přínos, bezpečnost, evidence. <b>Dvousečná:</b> na jedné straně nelze homeopatii odmítnout jen proto, že je označena jako alternativní; na druhé straně je pak zjištění o neprokázané účinnosti relevantním argumentem proti, který nelze odmítnout odkazem na odlišné paradigma.'},
{k:'jednostranny-pripad',t:'jednostranný případ',alt:'one-sided disease, case with few symptoms',d:'Případ s tak malým počtem použitelných symptomů, že nelze určit totalitu (§ 172–184; Hahnemann jej nazývá největší obtíží homeopatického léčení). Tři podoby: izolovaná lokální nemoc, případ maskovaný rozvinutou patologií, případ s nesdílným pacientem. <b>Postup:</b> vylučit, že jde jen o špatně odebraný případ; vytěžit maximum generalizací modalit; použít kauzu; podat nejlépe odpovídající lék a <b>využít reakci jako zdroj nových symptomů</b> (§ 180–184); odstranit překážky uzdravení.'},
{k:'kauza',t:'causa occasionalis',alt:'vyvolávající příčina, kauza',d:'Okolnost, která stav vyvolala (§ 5). V akutních případech bývá rozhodující a sama vede k léku (<span class="rx">Aconitum</span> po suchém chladném větru, <span class="rx">Arnica</span> po tupém poranění, <span class="rx">Rhus toxicodendron</span> po zmoknutí a přemáhání, <span class="rx">Staphysagria</span> po ponížení). V chronických případech se hledá formule <a href="#gl-nws">never well since</a>. Pozor na zkreslení: kauzu je třeba nechat vyplynout, nikoli nabídnout otázkou.'},
{k:'kentovy-observace',t:'Kentovy observace',alt:'Kent&#39;s twelve observations',d:'Dvanáct možných pozorování po podání léku, popsaných Kentem v <i>Lectures on Homoeopathic Philosophy</i>; nejpraktičtější rozhodovací nástroj follow-upu. Nejpříznivější jsou <b>krátká aggravace s rychlým zlepšením</b> a <b>návrat starých symptomů</b>; nejnepříznivější <b>dlouhá aggravace s trvalým zhoršením</b> a <b>aggravace patognomických symptomů</b>. Číslování se mezi vydáními liší — podstatný je obsah kategorií, ne pořadí.'},
{k:'keynote',t:'keynote',alt:'vodítko, klíčový symptom',d:'Symptom natolik charakteristický pro určitý lék, že na něj upozorní (pojem H. C. Allena) — zhoršení mezi 1.–3. hodinou u <span class="rx">Arsenicum album</span>, potřeba masáže u <span class="rx">Phosphorus</span>, lhostejnost k blízkým u <span class="rx">Sepia</span>. Keynote <b>otevírá hypotézu, nikoli předpis</b>: musí být potvrzen totalitou a kontrolou v Materii medice. Předpis podle jediného keynote bez potvrzení je metodická chyba, i když občas vyjde.'},
{k:'komplementarni-leky',t:'komplementární léky',alt:'complementary remedies',d:'Léky, které doplňují a dokončují působení jiného; jejich obrazy se prolínají a navazují — <span class="rx">Sulphur</span> ↔ <span class="rx">Nux vomica</span>, <span class="rx">Sepia</span> ↔ <span class="rx">Natrium muriaticum</span>, <span class="rx">Calcarea carbonica</span> ↔ <span class="rx">Belladonna</span>, <span class="rx">Silicea</span> ↔ <span class="rx">Thuja</span>. Uplatňují se při volbě <a href="#gl-druhy-predpis">druhého předpisu</a>, když se obraz po zlepšení posunul. Rozhodnout musí nová totalita, nikoli tabulka vztahů.'},
{k:'komplementarni-medicina',t:'komplementární medicína',alt:'complementary medicine',d:'Metoda používaná <b>vedle</b> konvenční léčby, která pokračuje bez změny. Odlišit od <b>alternativní</b> medicíny (místo konvenční léčby — nejrizikovější varianta, protože odkládá účinnou léčbu) a od <a href="#gl-integrativni-medicina">integrativní</a> medicíny (koordinovaná péče s jedním plánem). Klasická homeopatie v rámci profesního diplomu má být praktikována komplementárně či integrativně, nikdy alternativně.'},
{k:'kompletni-symptom',t:'kompletní symptom',alt:'complete symptom',d:'Symptom doplněný o všechny složky, které z něj činí použitelné vodítko: <b>L</b>okalizaci, <b>S</b>enzaci, <b>M</b>odalitu, <b>K</b>onkomitant (Bönninghausenova čtveřice LSMK), plus <b>čas</b> a <b>intenzitu/průběh</b>. „Bolí mě hlava“ je téma, nikoli symptom. Provozní kritérium kompletnosti: <em>lze z něj vybrat rubriku, která případ zúží?</em>'},
{k:'komplexni-homeopatie',t:'komplexní homeopatie',alt:'complex homeopathy',d:'Používání fixních směsí několika potencovaných látek podle indikace, bez individualizace — typické u volně prodejných přípravků. Z hlediska klasické nauky opouští jak podobnost aplikovanou na osobu, tak individualizaci, a je proto spíše indikačním předpisem než homeopatií v Hahnemannově smyslu (§ 273). Směšovat ji s klasickou metodou je u zkoušky chyba, i když je v praxi běžná.'},
{k:'konkomitant',t:'konkomitant',alt:'concomitant',d:'Symptom, který se objevuje <b>současně</b> s hlavní obtíží, přestože s ní zdánlivě nesouvisí — bolest hlavy s nutkáním na moč, angína s jednostranným výtokem z nosu, menstruace s bolestí v pravém rameni. Bönninghausen jim přikládal velkou váhu, protože neobvyklá kombinace individualizuje silněji než jednotlivý symptom. Součást <a href="#gl-kompletni-symptom">kompletního symptomu</a>.'},
{k:'konstitucni-lek',t:'konstituční lék',alt:'constitutional remedy',d:'Lék odpovídající dlouhodobému, celoživotnímu vzorci člověka, nikoli jen aktuální obtíži. Pojem není Hahnemannův (v Organonu je konstituce jednou z okolností, § 5) a vznikl v pozdější, zejména francouzské a kentovské tradici. <b>Upozornění:</b> typologie („typ Pulsatilla“) je pomůcka, ne kritérium — předepisovat podle vzhledu a povahového typu bez potvrzení symptomy je klasická začátečnická chyba.'},
{k:'kontextovy-efekt',t:'kontextový efekt',alt:'context effect',d:'Vliv všeho, co léčbu obklopuje, na její výsledek: chování terapeuta, délka konzultace, prostředí, očekávání, rituál podání, vysvětlení nemoci. Širší pojem než <a href="#gl-placebo">placebo</a>. Homeopatická konzultace naplňuje tyto faktory v mimořádné míře, což je hlavní kandidát na vysvětlení pozorovaných zlepšení — a zároveň argument pro zachování tohoto způsobu práce, ovšem bez tvrzení, že působí přípravek.'},
{k:'korsakov',t:'Korsakovova metoda',alt:'jednosklenicová metoda, potence K',d:'Výrobní metoda, kdy se pro všechny ředicí kroky používá <b>jediná nádoba</b>: obsah se vylije, na stěnách zůstane ulpělý zbytek (odhadem ~1 %), nádoba se doplní rozpouštědlem a provede se sukuse. Ředění je pouze přibližné, ale metoda umožňuje automatizovanou výrobu velmi vysokých potencí (10M, CM). Značí se <b>K</b> (200K). Protikladem je Hahnemannova mnohosklenicová metoda (značení C, CH) s definovaným ředěním.'},
{k:'lm-potence',t:'LM / Q potence',alt:'quinquagintamillesimal potency',d:'Hahnemannův pozdní vynález (6. vydání Organonu, § 270) s ředicím krokem <b>1 : 50 000</b>. Vychází se z C3; granule z 500 navlhčených (1 : 500) se rozpustí ve 100 kapkách (× 100). Značení LM1 / 0/1 / Q1 až LM30. Určeno pro <b>časté opakování s titrací dávky</b> (granule rozpuštěná ve sklenici vody, před každou dávkou protřepat, podávat po lžičkách). Vhodné u hluboké patologie, u citlivých a oslabených pacientů. <b>Pozor:</b> LM není „vysoká potence“ ve smyslu hloubky — je to jiná škála; LM1 není vyšší než C30.'},
{k:'matecna-tinktura',t:'matečná tinktura',alt:'tinctura matris, TM, Ø',d:'Výchozí hmotný extrakt pro potenciaci, obvykle etanolový. Z čerstvé rostliny se připravuje podle obsahu vlhkosti (typicky poměr 1 : 2), ze sušené drogy macerací či perkolací (typicky 1 : 10). U nerozpustných látek matečná tinktura neexistuje a nahrazuje ji <a href="#gl-triturace">triturace</a>. <b>Bezpečnostní poznámka:</b> matečné tinktury a nízké potence (Ø, D1–D3) toxických látek obsahují měřitelné množství látky a <em>nejsou</em> farmakologicky neškodné.'},
{k:'materia-medica',t:'Materia medica',alt:'MM',d:'Soubor popisů léků: pro každý lék seznam symptomů pozorovaných u zdravých v <a href="#gl-proving">provingu</a>, doplněný toxikologickými a klinickými daty. Zdrojová databáze celé homeopatie — repertorium i keynotes jsou z ní odvozeny. Tři typy: <b>čistá</b> (Hahnemann, Allen, Hering), <b>klinická a praktická</b> (Clarke, Boericke, Nash, Phatak), <b>interpretační a portrétová</b> (Kent, Vithoulkas, Vermeulen, Sankaran). U rozhodujícího symptomu se vrací ke zdroji.'},
{k:'materia-medica-pura',t:'Materia Medica Pura',alt:'Čistá materia medica',d:'Hahnemannovo dílo (6 svazků, 1811–1821) obsahující symptomy 66 léků získané provingy. Slovo „pura“ znamená, že obsahuje <b>jen pozorované</b> symptomy, nikoli teoretické vývody o účincích (§ 143–145) — každý symptom je číslovaný a s uvedením provera. Tento princip oddělení dat od výkladu je metodicky nejcennější část Hahnemannova odkazu a dnešní nerozlišování zdrojů v Materii medice je od něj odchylkou.'},
{k:'meta-analyza',t:'meta-analýza',alt:'meta-analysis',d:'Statistické sloučení výsledků více studií do souhrnného odhadu efektu. Stojí na vrcholu hierarchie evidence — <b>ale jen tehdy, mají-li vstupní studie kvalitu</b>: meta-analýza slabých studií je slabá evidence. U homeopatie je klíčové pozorování, že s rostoucí metodologickou kvalitou zahrnutých studií se efekt zmenšuje k nule (Linde 1999, Shang 2005, Mathie 2017).'},
{k:'mezihodnotitelska-shoda',t:'mezihodnotitelská shoda',alt:'inter-rater reliability',d:'Míra, v níž různí hodnotitelé dospějí k témuž výsledku u téhož materiálu. Studie, které nechaly více homeopatů nezávisle analyzovat tentýž zaznamenaný případ, nacházejí malý přesah zvolených rubrik a shodu ve výsledném léku často pod 50 %. <b>Důsledek:</b> bez reliability nelze budovat validitu. Obrana v praxi: písemné odůvodnění výběru symptomů, potvrzení v Materii medice, použití dvou metod a předem stanovená predikce.'},
{k:'miasma',t:'miasma',alt:'z řec. míasma — poskvrnění',d:'Hahnemannův pojem (<i>Die chronischen Krankheiten</i>, 1828) pro trvalou, hluboko založenou dispozici, která stojí za chronickou nemocí; bez zásahu do miasmatického pozadí zůstává léčba povrchní. <b>Nejde o „zkažený vzduch“ ani o mikroorganismus</b> — Hahnemann je příliš rané datum. Tři klasická: <a href="#gl-psora">psora</a>, <a href="#gl-sykoza">sykóza</a>, <a href="#gl-syfilis-miasma">syfilis</a>; později doplněno tuberkulinní a karcinosinní. Dnes hájitelné jako klasifikace <em>reakčních vzorců</em>, nikoli jako etiologické tvrzení.'},
{k:'modalita',t:'modalita',alt:'modality',d:'Okolnost, která symptom zhoršuje (v repertoriu &lt;, <i>aggravatio</i>) nebo zlepšuje (&gt;, <i>amelioratio</i>): teplo a chlad, pohyb a poloha, tlak a dotyk, denní čas, jídlo a pití, počasí a prostředí, duševní a sociální okolnosti. <b>Nejcennější kategorie repertorizace</b>, protože individualizuje nejsilněji. Zvláštní postavení má modalita útěchou: pacient zlepšený útěchou (<span class="rx">Pulsatilla</span>) a zhoršený útěchou (<span class="rx">Natrium muriaticum</span>, <span class="rx">Sepia</span>) se léčí docela jinak.'},
{k:'n-of-1',t:'N-of-1 studie',alt:'single patient trial',d:'Design, v němž se u <b>jednoho pacienta</b> opakovaně a zaslepeně střídá aktivní léčba a placebo v randomizovaném pořadí. Je to jediný design, který přímo testuje tvrzení o <em>individuální</em> reakci citlivého jedince — tedy právě tu námitku, kterou obor proti klasickým RCT vznáší. Designy tohoto typu jsou dostupné a homeopatie je využívá jen okrajově, což je věcná výtka směrem k oboru.'},
{k:'navrat-starych-symptomu',t:'návrat starých symptomů',alt:'return of old symptoms',d:'Krátkodobé vynoření symptomu, který pacient měl v minulosti a který vymizel (často po potlačující léčbě). Podle nauky je to <b>nejpříznivější prognostické znamení</b> — organismus „odbourává“ vrstvy v obráceném pořadí, než vznikly (čtvrté Heringovo pravidlo). Rozhodnutí: lék neopakovat, čekat, pacienta předem informovat, že je to očekávané, a zaznamenat časový rámec, ve kterém má odeznít.'},
{k:'nefalzifikovatelnost',t:'nefalzifikovatelnost',alt:'unfalsifiability',d:'Vlastnost teorie, kterou nemůže žádné pozorování vyvrátit, protože pro každý možný výsledek má připravené vysvětlení. Z hlediska filozofie vědy je to varovný signál: teorie, kterou nelze vyvrátit, neposkytuje o světě informaci. V homeopatii se projevuje ve výkladu follow-upu (zlepšení = lék, zhoršení = aggravace, žádná změna = překážka, nové symptomy = hlubší vrstva). <b>Obrana:</b> předem zapsaná predikce s časem a kritérii selhání.'},
{k:'nemoc',t:'nemoc',alt:'morbus',d:'V homeopatické doktríně (§ 11–12) <b>dynamická porucha vitální síly</b>, projevující se totalitou symptomů; hmotné a tkáňové změny jsou důsledkem, nikoli podstatou. Nemoc není entita existující nezávisle na pacientovi — proto „neexistují nemoci, existují nemocní“. Z tohoto pojetí plyne primát symptomů před teorií i zdůvodnění potenciace: chce-li lék působit na dynamickou poruchu, musí být sám v dynamické formě.'},
{k:'nhmrc',t:'NHMRC',alt:'Australian National Health and Medical Research Council',d:'Australská národní rada pro zdraví a lékařský výzkum. Ve zprávě z roku 2015 přezkoumala evidenci pro <b>61 zdravotních stavů</b> a uzavřela, že neexistuje spolehlivý důkaz účinnosti homeopatie u žádného z nich; doporučila ji nepoužívat u chronických a závažných stavů a tam, kde by mohla vést k odkladu účinné léčby. Homeopatické organizace metodiku zpochybnily; nezávislé přezkoumání ombudsmanem zásadní procesní pochybení nepotvrdilo.'},
{k:'nozod',t:'nozod',alt:'nosode',d:'Homeopatický lék připravený z <b>patologického</b> materiálu — sekretu, tkáně, kultury mikroorganismu nebo produktu nemoci: <span class="rx">Psorinum</span>, <span class="rx">Tuberculinum</span>, <span class="rx">Medorrhinum</span>, <span class="rx">Syphilinum</span>, <span class="rx">Carcinosinum</span>, <span class="rx">Pyrogenium</span>. Používá se <a href="#gl-intercurrentni-lek">intercurrentně</a> při stagnaci, při zřetelném miasmatickém obrazu, nebo jako lék volby, má-li pacient totalitu nozodu. Výroba podléhá nejpřísnějšímu režimu (inaktivace patogenů, doložený původ). Odlišit od <a href="#gl-sarkod">sarkodu</a>.'},
{k:'nws',t:'never well since (NWS)',alt:'„nikdy dobře od té doby, co…“',d:'Formule, kterou se v anamnéze hledá zlomový okamžik: „od té doby, co jsem měl chřipku / po porodu / po úmrtí otce / po té nehodě to nikdy nebylo dobré“. Spojuje <a href="#gl-kauza">kauzu</a> s časovou osou a v chudých případech může být jediné, co případ individualizuje. Odpovídají jí repertoriální rubriky <i>Generals — ailments from…</i>. Pozor: musí vyplynout z pacientova vyprávění, nesmí být nabídnuta otázkou.'},
{k:'obraz-leku',t:'obraz léku',alt:'drug picture, Arzneimittelbild',d:'Uspořádaný souhrn všeho, co o léku víme, v sedmi vrstvách: <b>1.</b> původ a surovina, <b>2.</b> jádro (téma jednou větou), <b>3.</b> duševní a emoční úroveň, <b>4.</b> generalia, <b>5.</b> partikulární symptomy, <b>6.</b> modality, <b>7.</b> vztahy a postavení léku. Doporučené pořadí učení je 2 → 3 → 6 → 4 → 5 → 1 → 7: jádro, psychika a modality nejdřív, protože právě ty rozhodují o volbě.'},
{k:'organon',t:'Organon',alt:'Organon der Heilkunst — Organon léčebného umění',d:'Základní text oboru: 291 číslovaných aforismů (paragrafů) tvořících uzavřený systém od definice úlohy lékaře po pokyny o dietě a přípravě léku. Šest vydání: 1810, 1819, 1824, 1829, 1833 a šesté, dokončené 1842 a vydané <b>až 1921</b> — proto se většina „klasické“ praxe formovala na pátém vydání a Hahnemannovu poslední pozici (LM potence, časté opakování, § 246) nezná. Při citaci je vhodné uvést, o které vydání jde.'},
{k:'paliace',t:'paliace',alt:'antipatický postup',d:'Potlačení symptomu pro úlevu, bez ambice léčit — podle § 52–56 využívá <a href="#gl-primarni-ucinek">primární účinek</a> proti symptomu, takže následná reakce organismu stav zhorší a vyžaduje zvyšování dávky. Hahnemann ji jako <em>strategii u léčitelných stavů</em> odmítal. <b>U nevyléčitelných a terminálních stavů je však paliace správným cílem</b>, nikoli selháním — a to je odpověď, kterou zkouška očekává.'},
{k:'paliativni-pece',t:'paliativní péče',alt:'palliative care',d:'Péče zaměřená na kvalitu života a zmírnění utrpení u nevyléčitelného onemocnění. V homeopatickém kontextu se mění cíl i technika: repertorizuje se <em>aktuální utrpení</em>, nikoli konstituce; volí se nižší potence s častějším opakováním nebo LM; <b>nepoužívají se Heringova pravidla</b> a jediným kritériem je zmírnění utrpení. Role je výhradně doplňková — analgezie, antiemetika a paliativní tým mají nezpochybnitelné místo. Slib vyléčení umírajícímu je závažné poškození.'},
{k:'patognomicky-symptom',t:'patognomický symptom',alt:'pathognomonic symptom',d:'Symptom, který definuje diagnózu — Koplikovy skvrny u spalniček, vezikuly v jednom dermatomu u herpes zoster, žloutenka u hepatitidy. Pro homeopatickou <em>volbu</em> léku je bezcenný, protože ho má každý pacient s danou nemocí. Pro <em>diagnózu, bezpečnost a sledování vývoje</em> je naopak nezbytný. Zaznamenat ano, repertorizovat ne.'},
{k:'person-centered',t:'person-centered care',alt:'péče zaměřená na osobu',d:'Dnes standardní koncept zdravotnických systémů se čtyřmi prvky: celá osoba místo diagnózy; vlastní vyprávění pacienta jako samostatná hodnota; společné rozhodování; výsledky hodnocené pacientem samým (<a href="#gl-proms">PROMs</a>). Homeopatický odběr případu je mu blízký, ale <b>není jeho vlastníkem</b> — konvenční medicína se k němu hlásí a v mnohém ho naplňuje lépe (validované nástroje, měřitelné výsledky). Pozornost k osobě navíc neomlouvá nedostatek evidence.'},
{k:'placebo',t:'placebo',alt:'placebo effect',d:'Zlepšení navozené léčbou bez specifického účinku. <b>Není to „nic“:</b> jsou doloženy fyziologické korreláty — aktivace endogenních opioidních systémů při placebové analgezii, změny dopaminergní aktivity u Parkinsonovy nemoci, změny kortizolu. Placebový a <a href="#gl-kontextovy-efekt">kontextový</a> efekt je největší u subjektivních symptomů (bolest, nevolnost, únava, úzkost, spánek), tedy právě u typického profilu obtíží v homeopatické praxi.'},
{k:'pluralismus',t:'pluralismus',alt:'pluralism',d:'Přístup podávající několik léků v definovaném sledu či střídání (drenážní lék, konstituční lék, akutní lék) — zejména ve francouzské tradici. Je pružnější u komplexních případů, ale opouští § 273 a ztrácí <b>interpretovatelnost reakce</b>: nelze zjistit, který lék působil. Protikladem je <a href="#gl-unicismus">unicismus</a>.'},
{k:'polychrest',t:'polychrest',alt:'z řec. poly + chrestos — mnohostranně užitečný',d:'Lék s rozsáhlým a hluboce prozkoumaným obrazem, použitelný v mnoha stavech: <span class="rx">Sulphur</span>, <span class="rx">Lycopodium</span>, <span class="rx">Calcarea carbonica</span>, <span class="rx">Phosphorus</span>, <span class="rx">Natrium muriaticum</span>, <span class="rx">Sepia</span>, <span class="rx">Arsenicum album</span>, <span class="rx">Pulsatilla</span>, <span class="rx">Nux vomica</span>, <span class="rx">Lachesis</span> a další. <b>Metodický důsledek:</b> polychresty jsou přítomny téměř v každé velké rubrice, takže v mřížce s mnoha velkými rubrikami „vyhrají“ bez ohledu na případ — to je artefakt, ne výsledek.'},
{k:'posologie',t:'posologie',alt:'posology',d:'Rozhodnutí o potenci, dávce a intervalu podávání. <b>Nižší potence a častější opakování</b> při nízké vitalitě, hrubé patologii, nejisté volbě léku, převaze místních symptomů a u paliativního cíle. <b>Vyšší potence jednorázově</b> při dobré reaktivitě, funkční poruše, jasné totalitě s duševními symptomy. Základní pravidlo napříč školami: <b>zlepšuje-li se pacient, lék se neopakuje.</b>'},
{k:'potence-c',t:'potence C (CH)',alt:'centesimální stupnice',d:'Škála, v níž každý krok znamená ředění <b>1 : 100</b> (1 díl předchozí potence + 99 dílů rozpouštědla) následované 100 sukusemi. Ø → C1 (10<sup>−2</sup>) → C2 → … → C12 (10<sup>−24</sup>, <a href="#gl-avogadro">Avogadrova mez</a>) → C30 → C200 → 1M (= 1000C) → 10M → CM. Nejběžnější v klasické praxi. Značení 30C nebo 30CH; pozor na odlišné 30K (<a href="#gl-korsakov">Korsakov</a>).'},
{k:'potence-d',t:'potence D (X, DH)',alt:'decimální stupnice',d:'Škála s ředicím krokem <b>1 : 10</b> a 10 sukusemi (v některých lékopisech 100). Běžná v německojazyčném prostoru a u volně prodejných přípravků. Převodní vztah, který stačí znát: <b>D2n = Cn</b> — tedy D12 = C6, D24 = C12 (Avogadrova mez), D60 = C30. Značení D6, 6X, 6DH.'},
{k:'potenciace',t:'potenciace',alt:'potentisation',d:'Postupné ředění léčivé látky kombinované s mechanickým tříbením — <a href="#gl-sukuse">sukusí</a> u tekutin, <a href="#gl-triturace">triturací</a> u nerozpustných látek. Nauka nepovažuje samo ředění za dostatečné; rozhodující je podle ní mechanický vklad energie (odtud <a href="#gl-dynamizace">dynamizace</a>, § 269). Potenciace je vnitřně konzistentním důsledkem pojetí nemoci jako <em>dynamické</em> poruchy, nikoli trikem pro snížení toxicity.'},
{k:'potlaceni',t:'potlačení (suprese)',alt:'suppression',d:'Odstranění projevu nemoci bez léčby poruchy, které podle nauky vede k přesunu poruchy na hlubší, vitálně důležitější úroveň (§ 184–203). Doktrinální příklad: lokální kortikoid na ekzém → astma. <b>Nutná výhrada:</b> tatáž sekvence je v alergologii popsána jako <em>atopický marš</em>, tedy přirozený vývoj atopie u predisponovaných dětí, a kauzální podíl léčby doložen není. Adept má umět vyložit doktrinální pojem a zároveň ho neprezentovat jako prokázaný mechanismus.'},
{k:'pozorovani',t:'pozorování (§ 90)',alt:'observation',d:'Terapeutovo vlastní smyslové pozorování pacienta, jemuž Organon dává stejnou váhu jako jeho výpovědi: způsob vstupu a usazení, termoregulační chování, pleť a nehty, zápach, tempo a hlasitost řeči, gesta, vztah k doprovodu, místa, kde odbočí nebo ztichne. <b>Pravidlo zápisu:</b> do záznamu patří jen to, co by na videu viděl kdokoli jiný — výklad („úzkostný“, „somatizuje“) patří do oddělené kolonky hypotéz.'},
{k:'prekazky-vyleceni',t:'překážky uzdravení',alt:'obstacles to cure',d:'Faktory, které brání reakci na správně zvolený lék (§ 3, § 260): stimulancia a životní styl (káva, alkohol, nikotin, spánková deprivace), chronická expozice (plíseň, pracovní chemie, směnná práce), medikace, ložiskové faktory (zuby, tonzily, sinusy), nutriční a metabolické nedostatky, psychosociální zátěž, tradičně antidotující vlivy, a <b>nesprávné podání léku</b> — to bývá nejčastější příčina „žádné změny“ a zjišťuje se první. Při stagnaci se hledá překážka <em>dřív</em>, než se zvyšuje potence.'},
{k:'primarni-ucinek',t:'primární účinek',alt:'Erstwirkung',d:'Přímý účinek látky na organismus (§ 63–65). U kávy bdělost, vzrušení, zrychlený puls. Na něm staví <a href="#gl-paliace">antipatická (paliativní)</a> léčba, která podává látku s primárním účinkem <em>protikladným</em> symptomu — s krátkou úlevou a následným zhoršením. Homeopatie naopak volí látku s primárním účinkem symptomu <em>podobným</em>, takže proti nemoci působí <a href="#gl-sekundarni-ucinek">sekundární reakce</a>.'},
{k:'proving',t:'proving (HPT)',alt:'homeopathic pathogenetic trial, Arzneimittelprüfung',d:'Systematické podávání homeopaticky připravené látky <b>zdravým</b> dobrovolníkům se záznamem všech změn stavu (§ 105–145). U nemocného by nebylo možné odlišit symptom nemoci od symptomu léku. Proving je zdrojem Materie mediky, a tedy epistemickým základem oboru — a zároveň jeho nejzranitelnějším místem: moderní zaslepené provingy nacházejí malé nebo nevýznamné rozdíly proti placebu.'},
{k:'profylaxe',t:'homeopatická profylaxe',alt:'homeoprophylaxis',d:'Podávání homeopatického přípravku zdravým lidem s cílem předejít nákaze. <b>Překračuje Organon i evidenci:</b> nástroj, který se tomu nejvíc blíží — <a href="#gl-genus-epidemicus">genus epidemicus</a> (§ 100–104) — je určen k <em>léčbě již nemocných</em>, nikoli k prevenci u zdravých. Homeopatický přípravek <b>není a nesmí být prezentován jako alternativa vakcinace</b>: vakcíny mají doloženou účinnost a známý imunologický mechanismus, homeopatická profylaxe ani jedno. Doporučení vedoucí k odmítnutí očkování není odborně obhajitelné a je disciplinárně i právně rizikové; ECH i národní lékařské homeopatické společnosti to opakovaně potvrdily.'},
{k:'proms',t:'PROMs',alt:'patient-reported outcome measures',d:'Validované nástroje pro měření výsledků tak, jak je hodnotí pacient sám (MYMOP, ORIDL/ODI, SF-36, dotazníky kvality života). Pro homeopatii jsou příležitostí, nikoli hrozbou: dovolují učinit „celkový stav a energii“ — tedy právě to, co obor sleduje — <b>měřitelným a srovnatelným</b> ukazatelem, a odpovídají na námitku, že studie měří nesprávné cílové ukazatele.'},
{k:'prover',t:'prover',alt:'účastník provingu',d:'Dobrovolník, který v <a href="#gl-proving">provingu</a> užívá testovanou látku a vede denní záznam symptomů vlastními slovy s uvedením času. Musí dodržovat režim (žádné jiné léky, omezení stimulancií) a <b>nesmí během provingu sdílet zážitky s ostatními provery</b> — sociální nákaza symptomů je dobře popsaný jev, který znehodnotí celý proving. Hahnemann považoval za nejlepšího provera lékaře na sobě samém (§ 137, 141).'},
{k:'psora',t:'psora',alt:'psorické miasma',d:'První a podle Hahnemanna nejrozšířenější <a href="#gl-miasma">miasma</a>, historicky spojené s potlačenou svrabí a kožními vyrážkami. Reakční typ: <b>funkční porucha bez destrukce</b> — nedostatečnost, hypofunkce, svědění, alergie, funkční dyspepsie, astma, úzkost z nedostatku. Klíč: „chybí“. Léky: <span class="rx">Sulphur</span>, <span class="rx">Psorinum</span>, <span class="rx">Calcarea carbonica</span>, <span class="rx">Lycopodium</span>, <span class="rx">Arsenicum album</span>.'},
{k:'publikacni-zkresleni',t:'publikační zkreslení',alt:'publication bias',d:'Systematická chyba vznikající tím, že studie s pozitivním výsledkem jsou publikovány častěji a rychleji než studie negativní. Důsledkem je, že literatura vypadá příznivěji než realita. V meta-analýzách se hledá pomocí <a href="#gl-funnel-plot">funnel plotu</a>. U homeopatie se týká jak klinických studií, tak <a href="#gl-proving">provingů</a> — ECH guidelines proto výslovně žádají publikovat i provingy, které nic nenalezly.'},
{k:'rct',t:'randomizovaná kontrolovaná studie (RCT)',alt:'randomised controlled trial',d:'Studie, v níž jsou účastníci náhodně rozděleni do skupin (aktivní léčba versus placebo či srovnávací léčba), ideálně se <a href="#gl-zaslepeni">zaslepením</a> a <a href="#gl-alokacni-utajeni">alokačním utajením</a>. Randomizace vyrovnává známé i neznámé zaměňující faktory, a je proto jediným způsobem, jak oddělit specifický efekt od placeba a přirozeného průběhu. Pro individualizovanou homeopatii se používá varianta, kde homeopat volí lék podle svých pravidel a randomizuje se přípravek versus placebo.'},
{k:'regrese-k-prumeru',t:'regrese k průměru',alt:'regression to the mean',d:'Statistický jev: u fluktuujícího stavu je po extrémní hodnotě pravděpodobnější hodnota blíž průměru. Pacient přichází k terapeutovi, <b>když je nejhůř</b> — a další vývoj bude statisticky lepší nezávisle na jakékoli léčbě. Je to hlavní důvod, proč nekontrolované pozorování vlastní praxe systematicky nadhodnocuje účinnost, a proč ani dvě stě let zkušenosti neposkytuje doklad o účinnosti.'},
{k:'relaps',t:'relaps',alt:'návrat symptomů',d:'Návrat <b>téhož</b> obrazu po období zlepšení, obvykle po týdnech až měsících. Znamená, že lék byl správný, ale jeho působení se vyčerpalo. <b>Rozhodnutí:</b> zopakovat tentýž lék v téže potenci a zaznamenat, jak dlouho působil. Zkracuje-li se doba působení opakovaně, hledat <a href="#gl-prekazky-vyleceni">překážky uzdravení</a>, a teprve potom zvážit vyšší potenci nebo přechod na LM. Odlišit od <a href="#gl-aggravace">aggravace</a> a od zhoršení nemoci.'},
{k:'repertorium',t:'repertorium',alt:'repertory',d:'Obrácený index Materie mediky: zatímco Materia medica řadí podle léků (lék → symptomy), repertorium podle symptomů (symptom → léky). Hlavní díla: Bönninghausenovo <i>Therapeutisches Taschenbuch</i> (1846, 125 léků, vysoká spolehlivost údaje), Kentovo <i>Repertory</i> (1897, ~650 léků, primát duševních symptomů), moderní syntézy <i>Synthesis</i> a <i>Complete Repertory</i>. Repertorium <b>zužuje okruh kandidátů</b>; lék určuje Materia medica.'},
{k:'repertorizace',t:'repertorizace',alt:'repertorisation',d:'Postup, jímž se vybrané symptomy přeloží na rubriky a porovnají se s obsahem repertoria, aby se zúžil okruh kandidátních léků. Osm kroků: výběr 6–10 symptomů → překlad na rubriky → určení váhy → volba eliminační rubriky → mřížka → vyhodnocení pokrytí a součtu → výběr 3–5 kandidátů → <b>rozhodnutí v Materii medice</b>. Čísla v mřížce nejsou míra podobnosti, nýbrž pomůcka pro uspořádání.'},
{k:'repertorizacni-mrizka',t:'repertorizační mřížka',alt:'repertorisation grid',d:'Tabulka s rubrikami v řádcích, léky ve sloupcích a gradací léku v polích. Hodnotí se dvě čísla: <b>počet rubrik, které lék pokrývá</b> (primárně) a <b>vážený součet gradací</b> (sekundárně). Lék chybějící v rubrice, která vyjadřuje silný symptom pacienta, tento symptom nepokrývá — a totalita tedy není naplněna, i kdyby měl nejvyšší součet. Z mřížky se nepředepisuje.'},
{k:'rise-leku',t:'říše léků',alt:'kingdoms',d:'Zařazení léků podle původu suroviny: <b>rostliny</b> (téma citlivosti a reaktivity, členění podle čeledí), <b>minerály a soli</b> (struktura a nedostatek, systematizovatelné podle periodické tabulky), <b>živočichové</b> (vztah, soupeření, přežití), <b>nozody a sarkody</b> (miasmatické pozadí a stagnace), <b>imponderabilia</b> (fyzikální vlivy — magnetismus, světlo, záření). Říšová charakteristika je interpretační pomůcka, nikoli výsledek provingů, a nesmí přebít symptomatickou shodu.'},
{k:'rubrika',t:'rubrika',alt:'rubric',d:'Záznam v repertoriu: symptom či okolnost se seznamem léků, které ji obsahují, a s jejich <a href="#gl-gradace-leku">gradací</a>. Rubriky jsou uspořádány hierarchicky (rubrika → podrubrika → pod-podrubrika) a platí <b>zděděná příslušnost</b>: lék z podrubriky patří i do rubriky nadřazené, nikoli naopak. Proto zvětšení rubriky nikdy lék neztratí, zúžení ano. Velikost rubriky má odpovídat jistotě symptomu; rubriky nad ~200 léků jsou pro výběr téměř bezcenné.'},
{k:'salutogeneze',t:'salutogeneze',alt:'salutogenesis',d:'Pojem Aarona Antonovského: otázka není jen „co působí nemoc“ (patogeneze), ale <b>„co udržuje zdraví“</b>. Souvisí s pojmem resilience — schopností systému vrátit se po perturbaci. V současné medicíně uznávaný koncept ve veřejném zdraví a psychiatrii; poskytuje jazyk, v němž se homeopatický zájem o „celkový stav a energii“ dá formulovat srozumitelně pro konvenční prostředí.'},
{k:'sarkod',t:'sarkod',alt:'sarcode',d:'Homeopatický lék připravený ze <b>zdravé</b> tkáně nebo sekretu, typicky orgánový či hormonální: <span class="rx">Thyroidinum</span> (štítná žláza), dále <i>Adrenalinum</i>, <i>Insulinum</i>, <i>Ovarinum</i>. Odlišit od <a href="#gl-nozod">nozodu</a>, který vychází z patologického materiálu.'},
{k:'sekundarni-ucinek',t:'sekundární účinek',alt:'Nachwirkung, reakce vitální síly',d:'Protikladná odpověď organismu, která následuje po <a href="#gl-primarni-ucinek">primárním účinku</a> látky (§ 63–65). U kávy následná ospalost a sklíčenost. Na tomto mechanismu nauka staví vysvětlení, proč paliace krátkodobě pomáhá a dlouhodobě škodí, a proč homeopatický lék může krátkodobě zhoršit (aggravace) a dlouhodobě zlepšit. Farmakologické protějšky: rebound fenomén, receptorová up-regulace při chronické blokádě.'},
{k:'senzace',t:'senzace',alt:'sensation',d:'Kvalita pocitu vyjádřená pacientovými vlastními slovy nebo obrazem: „jako by mi tam zatloukli hřebík“, „jako by mi v žaludku plavala živá ryba“, „jako by mi po kůži tekla studená voda“. Součást <a href="#gl-kompletni-symptom">kompletního symptomu</a> a častý zdroj <a href="#gl-srp">SRP</a> symptomů. Ptát se otevřeně („jaký to je pocit?“) — nabídnutí dvou možností („pulzující, nebo tupé?“) vytlačí právě tu senzaci, která by případ individualizovala.'},
{k:'simile',t:'simile',alt:'similimum',d:'Lék, jehož obraz je nejpodobnější totalitě symptomů pacienta — tedy hledaný lék. Termín <b>similimum</b> se užívá pro nejlépe odpovídající lék vůbec, <i>simile</i> pro lék dostatečně podobný. Podobnost lze hledat na třech úrovních: jednotlivých symptomů (keynotes), celkového vzorce (kentiánská totalita) a tématu či <a href="#gl-centralni-senzace">centrální senzace</a> (moderní směry) — a právě volba úrovně je jedním z důvodů rozptylu mezi homeopaty.'},
{k:'socialni-nakaza',t:'sociální nákaza symptomů',alt:'social contagion of symptoms',d:'Šíření symptomů mezi lidmi ve skupině na základě komunikace a očekávání, nikoli společné příčiny — dobře popsaný jev (například u hromadných psychogenních reakcí). V <a href="#gl-proving">provingu</a> je hlavním důvodem, proč provery nesmějí sdílet zážitky, a hlavní metodickou výtkou proti skupinovým „meditativním“ provingům, kde účastníci zpravidla sedí pohromadě a své dojmy si vyměňují.'},
{k:'spolecny-symptom',t:'společný (nespecifický) symptom',alt:'common symptom',d:'Symptom, který má většina pacientů s danou nemocí nebo většina lidí vůbec: horečka u chřipky, svědění u ekzému, bolest při polykání u angíny, únava. § 153 je výslovně odmítá jako „obecné a nepřesně určené“ — pro volbu léku mají <b>nulovou váhu</b>. <b>Terminologická past:</b> nezaměňovat se <a href="#gl-generalia">generálním symptomem</a>, který má naopak váhu vysokou; v češtině se obojí občas přeloží slovem „obecný“.'},
{k:'srovnavaci-mm',t:'srovnávací Materia medica',alt:'comparative materia medica',d:'Umění odlišit léky, které se v analýze objevují spolu. Rozhodující nejsou seznamy symptomů, nýbrž <b>jeden či dva znaky, které jdou proti sobě</b>: <span class="rx">Bryonia</span> se zhoršuje každým pohybem, <span class="rx">Rhus toxicodendron</span> prvním pohybem a pokračujícím se zlepšuje; <span class="rx">Natrium muriaticum</span> má uzavřené hoře, <span class="rx">Sepia</span> lhostejnost; <span class="rx">Pulsatilla</span> je horkokrevná a útěchou zlepšená, <span class="rx">Silicea</span> zimomřivá. Tyto rozhodující rozdíly se učí nazpaměť.'},
{k:'srp',t:'SRP — symptomy podivné, vzácné a zvláštní',alt:'strange, rare and peculiar; auffallend, sonderlich, ungewöhnlich',d:'Kategorie z § 153: symptomy nápadné, zvláštní, neobvyklé a charakteristické, na které se má při volbě léku hledět „zvláště a téměř výhradně“. Symptom je SRP, jestliže nevyplývá z diagnózy, je paradoxní (zánět zlepšený chladem u zimomřivého pacienta), je neobvykle přesně lokalizovaný či časovaný, má neobvyklou <a href="#gl-senzace">senzaci</a>, nebo neobvyklý <a href="#gl-konkomitant">konkomitant</a>. Jediný silný SRP symptom může vážit více než tři generalia, a přebíjí proto hierarchii.'},
{k:'sugestivni-otazka',t:'sugestivní otázka',alt:'leading question',d:'Otázka, která napovídá odpověď — „zhoršuje se to v teple?“, „nezačalo to po nějakém stresu?“, „je to pulzující, nebo tupé?“. Hahnemann ji v § 87 výslovně zakazuje. Vytváří symptomy, které jsou artefaktem rozhovoru, a tím kontaminuje celou další analýzu. Obrana: otevřené otázky, nabídka <em>všech</em> možností včetně „nevšiml jsem si“, a označování spontánně uvedených symptomů v záznamu.'},
{k:'sukuse',t:'sukuse',alt:'succussio',d:'Rytmické, silné protřepání tekutiny s úderem o pružnou podložku (Hahnemann používal knihu v kožené vazbě); standardně 100 úderů na krok centesimální škály. Podle nauky je to právě tento mechanický vklad, nikoli samo ředění, co lék „dynamizuje“ — proto je sukuse součástí lékopisných postupů. U nerozpustných látek plní tuto funkci <a href="#gl-triturace">triturace</a>.'},
{k:'supervizor',t:'supervizor',alt:'supervisor',d:'Osoba, která v <a href="#gl-proving">provingu</a> vede jednoho až tři provery: je s nimi v pravidelném kontaktu, doptává se na modality, ověřuje, zda symptom není součástí jejich obvyklého stavu, rozhoduje o ukončení podávání a zajišťuje bezpečnost. <b>Nesmí znát testovanou látku</b> — jinak by doptáváním sugeroval očekávané symptomy. Role je proto oddělena od hlavního zkoušejícího, který spravuje kód a provádí dekódování.'},
{k:'syfilis-miasma',t:'syfilitické miasma',alt:'syphilitic miasm, lues',d:'Třetí klasické <a href="#gl-miasma">miasma</a>, historicky spojené s potlačenou syfilidou. Reakční typ: <b>destrukce a ulcerace</b> — rozpad tkání, vředy, kostní a chrupavčité léze, deformity, noční zhoršení, sebedestruktivní a násilné mentální obrazy, alkoholismus. Klíč: „ničí“. Léky: <span class="rx">Mercurius solubilis</span>, <span class="rx">Syphilinum</span>, <span class="rx">Aurum metallicum</span>, <span class="rx">Kalium iodatum</span>, <span class="rx">Nitricum acidum</span>, <span class="rx">Fluoricum acidum</span>.'},
{k:'sykoza',t:'sykóza',alt:'sycotic miasm',d:'Druhé klasické <a href="#gl-miasma">miasma</a>, historicky spojené s potlačenou kapavkou. Reakční typ: <b>nadbytek, novotvorba, infiltrace</b> — kondylomata, papilomy, cysty, myomy, revmatické infiltráty, katarální výtoky; mentálně tajnůstkářství, pocit viny, fixní ideje a rituály. Klíč: „přebývá a schovává se“. Léky: <span class="rx">Thuja occidentalis</span>, <span class="rx">Medorrhinum</span>, <span class="rx">Natrium sulphuricum</span>, <span class="rx">Nitricum acidum</span>.'},
{k:'systemovy-pristup',t:'systémový přístup',alt:'systems approach',d:'Pohled, který chápe organismus jako síť interagujících prvků s vlastnostmi neodvoditelnými z prvků samotných (emergence, nelinearita, bodové zlomy). V současné medicíně má etablované podoby: homeostáza a <a href="#gl-alostaze">alostáze</a>, neuroimunoendokrinní regulace, síťová medicína, resilience a <a href="#gl-salutogeneze">salutogeneze</a>, biopsychosociální model. Homeopatie je systémová ve <b>způsobu pozorování</b>, nikoli v doloženém mechanismu: systémová teorie jí dává jazyk, nikoli důkaz.'},
{k:'tcih',t:'TCIH',alt:'Traditional, Complementary and Integrative Healthcare',d:'Dnešní zastřešující pojem pro tradiční, komplementární a integrativní péči, který nahradil starší „CAM“. Posun není kosmetický: zdůrazňuje <b>integraci do systému péče a regulaci</b> místo protikladu k medicíně. Odpovídá strategii WHO pro tradiční medicínu, jejíž cíle jsou znalostní základna a národní politiky, <b>kvalita a bezpečnost</b>, a integrace do zdravotních systémů — nikoli potvrzení účinnosti jednotlivých metod.'},
{k:'tcm',t:'tradiční čínská medicína',alt:'TČM, TCM',d:'Léčebný systém pracující s rovnováhou <i>qi</i>, jin a jang, pěti prvků a s průchodností meridiánů; léčba doplňuje chybějící a rozptyluje nadbytečné podle diagnostického vzorce (syndromu). Používá bylinné směsi v hmotných dávkách, akupunkturu, moxu a dietetiku. Na rozdíl od homeopatie nevychází z provingem zjištěné podobnosti a nepracuje s potenciací. <b>Doložená rizika:</b> hepatotoxicita, kontaminace, aristolochové kyseliny (nefrotoxicita a karcinogenita), interakce.'},
{k:'totalita-symptomu',t:'totalita symptomů',alt:'totality of symptoms',d:'Soubor symptomů, které dohromady <b>individualizují</b> případ, tedy odlišují tohoto pacienta od jiných se stejnou diagnózou (§ 7, § 18). Není to součet všech stížností: symptomy, které má každý pacient s danou nemocí, do totality nepatří, protože nerozlišují. Zahrnuje modality, senzace, generalia, duševní stav, konkomitanty a kauzu. Je to jediné vodítko k volbě léku, protože porucha sama není smyslům přístupná (§ 6).'},
{k:'triturace',t:'triturace',alt:'trituratio',d:'Roztírání nerozpustné látky s laktózou v třecí misce po stanovenou dobu a v definovaných fázích (u C poměr 1 : 99, u D 1 : 9). Používá se u kovů, minerálů a nerozpustných solí a nahrazuje pro první potence <a href="#gl-matecna-tinktura">matečnou tinkturu</a>. Z třetí centesimální triturace (C3) se vychází i při přípravě <a href="#gl-lm-potence">LM potencí</a>.'},
{k:'unicismus',t:'unicismus',alt:'unicism',d:'Zásada, že v jednom čase se podává <b>jediný lék</b> v jediné potenci (§ 273). Zdůvodnění je epistemické, a proto nejsilnější: podáme-li dvě látky, nevíme, která působila — a Materia medica je přitom postavena na provingech jednotlivých látek, takže o kombinaci nemáme žádná data. Unicismus je tedy požadavek na <b>interpretovatelnost reakce</b>. Protiklady: <a href="#gl-pluralismus">pluralismus</a> a <a href="#gl-komplexni-homeopatie">komplexní homeopatie</a>.'},
{k:'urovne-zdravi',t:'úrovně zdraví',alt:'levels of health (Vithoulkas)',d:'Model George Vithoulkase, který řadí pacienty do úrovní (obvykle 1–12) podle reaktivity, hloubky patologie a rodinné zátěže; z úrovně se vyvozuje prognóza, volba potence i očekávaný typ reakce. Užitečné pro rozhodování o potenci a opakování. <b>Metodické riziko:</b> zařazení je expertní úsudek, a model proto umožňuje vysvětlit selhání post hoc („pacient byl na nízké úrovni“) — tedy podobu nefalzifikovatelnosti.'},
{k:'uzdraveni',t:'uzdravení',alt:'curatio',d:'Podle § 2 odstranění celé totality symptomů — „rychle, mírně a trvale“, nejkratší, nejbezpečnější a nejméně škodlivou cestou a podle jasně pochopitelných důvodů. Není to zmizení hlavní stížnosti: kritériem je zlepšení celkového stavu a energie a správný směr podle <a href="#gl-heringova-pravidla">Heringových pravidel</a>. Vymizení lokálního symptomu se zhoršením celkového stavu není uzdravení, nýbrž <a href="#gl-potlaceni">potlačení</a>.'},
{k:'vitalismus',t:'vitalismus',alt:'vitalism',d:'Směr předpokládající zvláštní životní princip nad rámec fyziky a chemie. V 19. století legitimní vědecká hypotéza (Bichat, Müller); po syntéze urey (Wöhler 1828), objasnění fermentace a rozvoji biochemie byl jako vysvětlující teorie opuštěn. Dnešní věda pojem životní síly neuznává. Moderní homeopatická literatura proto <a href="#gl-vitalni-sila">vitální sílu</a> často reinterpretuje jako samoregulační kapacitu organismu — čtivě, ale s tím, že mění význam Hahnemannova tvrzení a mechanismus neřeší.'},
{k:'vitalni-sila',t:'vitální síla (dynamis)',alt:'Lebenskraft, dynamis, vital force',d:'Nehmotný, samočinně regulující princip, který podle § 9–12 udržuje organismus v harmonickém chodu; tělo bez ní je „neschopno vnímání, činnosti i sebeudržení“ (§ 10). Nemoc je jejím rozladěním (§ 11), symptomy jsou jejím jazykem (§ 6–7) a lék musí být proto rovněž v dynamické formě (§ 269). Pojem patří do <a href="#gl-vitalismus">vitalismu</a>; dnes bývá reinterpretován jako samoregulační a adaptivní kapacita organismu.'},
{k:'zakladni-obdobi',t:'základní období (baseline)',alt:'baseline period',d:'Fáze <a href="#gl-proving">provingu</a> před podáním látky (obvykle 1–4 týdny), v níž prover zaznamenává svůj běžný stav. <b>Bez ní nelze u žádného symptomu tvrdit, že je nový</b> — a protože zdravý člověk zaznamená za několik týdnů intenzivního sebepozorování desítky jevů bez jakéhokoli léku, je absence základního období sama dostatečným důvodem, proč proving nelze použít jako zdroj Materie mediky.'},
{k:'zakon-podobnosti',t:'zákon podobnosti',alt:'similia similibus curentur',d:'Základní pravidlo volby léku: „podobné ať se léčí podobným“ — podává se látka, která u zdravého vyvolává symptomy nejpodobnější symptomům nemocného (§ 22, 26). Gramatický tvar je významný: <i>curentur</i> je konjunktiv, tedy <b>terapeutické doporučení</b>, nikoli tvrzení o přírodní nutnosti (<i>curantur</i>). Hahnemannova originalita není v myšlence samé (Hippokratés, Paracelsus), nýbrž v tom, že ji doplnil metodou získávání dat (provingy) a metodou přípravy (potenciace).'},
{k:'zaslepeni',t:'zaslepení',alt:'blinding, masking',d:'Opatření, kdy účastníci studie nevědí, do které skupiny patří. <b>Jednoduché</b> — nevědí pacienti; <b>dvojité</b> — nevědí pacienti ani terapeuti či hodnotitelé; někdy je zaslepen i statistik. U subjektivních ukazatelů je zaslepení hodnotitele rozhodující. Námitka, že „zaslepení ruší terapeutický vztah“, je zavádějící: zaslepuje se <em>přípravek</em>, konzultaci dostanou obě skupiny stejně.'},
{k:'zdravi',t:'zdraví',alt:'sanitas',d:'Podle § 9 stav, kdy <a href="#gl-vitalni-sila">vitální síla</a> udržuje harmonický chod organismu. Vithoulkasova rozvinutější definice pracuje se třemi úrovněmi: na tělesné nepřítomnost bolesti, na emoční klid a schopnost cítit lásku, na mentální jasnost a schopnost soustředit se na tvůrčí cíl. Zdraví tedy není jen absence diagnózy — v tom se homeopatické pojetí blíží definici WHO a konceptu <a href="#gl-person-centered">person-centered care</a>.'},
{k:'zjednodusena-registrace',t:'zjednodušená registrace',alt:'simplified registration procedure',d:'Režim podle čl. 14 směrnice 2001/83/ES: homeopatický přípravek lze registrovat <b>bez předložení dokladů o terapeutické účinnosti</b>, pokud je podáván perorálně či zevně, na obalu <b>není uvedena žádná terapeutická indikace</b> a je dostatečně naředěn (uvádí se nejvýše 1 : 10 000 matečné tinktury, resp. 1/100 nejmenší alopatické dávky u látek na předpis). <b>Registrace tedy hodnotí kvalitu a bezpečnost, nikoli účinnost</b> — argument „je to registrovaný lék, tedy prokázaný“ je nesprávný.'},
/* --- doplňující hesla bez přímého výskytu v textu --- */
{k:'hahnemann',t:'Hahnemann, Samuel',alt:'1755–1843',d:'Christian Friedrich Samuel Hahnemann, německý lékař, chemik a překladatel, zakladatel homeopatie. Narozen v Meissenu, promoval 1779 v Erlangenu. Chininový pokus 1790, publikace principu 1796, <i>Organon</i> 1810, <i>Materia Medica Pura</i> 1811–21, <i>Die chronischen Krankheiten</i> 1828–30. Od 1835 v Paříži, kde vyvinul <a href="#gl-lm-potence">LM potence</a>; zemřel 1843, pohřben na Père-Lachaise.',see:['ch1']},
{k:'kent',t:'Kent, James Tyler',alt:'1849–1916',d:'Americký lékař, autor <i>Repertory of the Homoeopathic Materia Medica</i> (1897), <i>Lectures on Homoeopathic Philosophy</i> a <i>Lectures on Materia Medica</i>. Zavedl důraznou <a href="#gl-hierarchie-symptomu">hierarchii symptomů</a> s primátem duševních symptomů, práci s vysokými potencemi a dvanáct <a href="#gl-kentovy-observace">observací</a> follow-upu. Jeho vliv na evropskou klasickou homeopatii je dominantní — proto je dobré vědět, že řada „hahnemannovských“ pravidel je vlastně kentovská.',see:['ch3','ch5','ch9']},
{k:'bonninghausen',t:'Bönninghausen, Clemens von',alt:'1785–1864',d:'Právník a botanik, Hahnemannův přítel a jeden z nejvlivnějších homeopatů 19. století. Autor <i>Therapeutisches Taschenbuch</i> (1846) a systému práce s <a href="#gl-modalita">modalitami</a> a <a href="#gl-konkomitant">konkomitanty</a>; zavedl princip <a href="#gl-generalizace">generalizace</a> a tabulky vztahů léků (concordances). Jeho přístup je dnes protiváhou kentianismu a je metodou volby u akutních případů, u dětí a u nesdílných pacientů.',see:['ch3','ch5']},
{k:'hering',t:'Hering, Constantine',alt:'1800–1880',d:'Zakladatel americké homeopatie, autor desetisvazkových <i>Guiding Symptoms of our Materia Medica</i>, v nichž značí klinicky potvrzené symptomy — proto je to dodnes nejlepší zdroj pro ověření symptomu. Provedl proving <span class="rx">Lachesis</span>. Jeho jméno nesou <a href="#gl-heringova-pravidla">Heringova pravidla</a>, ačkoli dnešní čtyřbodovou podobu sám nesepsal.',see:['ch1','ch6','ch9']},
{k:'vithoulkas',t:'Vithoulkas, George',alt:'* 1932',d:'Řecký homeopat, autor <i>The Science of Homeopathy</i> (1978) a <i>Materia Medica Viva</i>; zásadní vliv na evropské postgraduální vzdělávání. Rozvinul kentovskou hierarchii, definici zdraví na třech úrovních a model <a href="#gl-urovne-zdravi">úrovní zdraví</a> s prognostickým využitím.',see:['ch1','ch3','ch11']},
{k:'sankaran',t:'Sankaran, Rajan',alt:'moderní směr',d:'Indický homeopat, autor senzační metody: za symptomy leží <a href="#gl-centralni-senzace">centrální senzace</a> a vitální pocit, podle nichž se léky řadí do říší a rostlinných čeledí. Otevírá cestu k lékům bez dobrého repertoriálního pokrytí a dává učení Materie mediky strukturu; metodickým rizikem je vyšší podíl interpretace a tím i projekce terapeuta.',see:['ch5','ch6']},
{k:'scholten',t:'Scholten, Jan',alt:'Element Theory',d:'Nizozemský homeopat, autor systematiky minerálních léků podle <b>periodické tabulky</b>: řada (série) určuje téma života, skupina (stage) fázi jeho rozvoje, a z pozice prvku lze obraz léku <em>dedukovat</em>. Umožnil systematizovat stovky dříve nepoužívaných léků. Hlavní výtka klasiků: deduktivní odvození obrazu bez provingu obrací Hahnemannovu metodu (§ 20–21) — z empirické disciplíny se stává teoretická.',see:['ch5']},
{k:'oscillococcinum',t:'Oscillococcinum',alt:'Anas barbariae hepatis et cordis extractum 200K',d:'Nejprodávanější homeopatický přípravek světa, používaný u chřipkových onemocnění. Připraven z autolyzátu jater a srdce kachny; název odkazuje na „oscilokoky“, které jeho tvůrce Joseph Roy v roce 1917 považoval za vyvolavatele chřipky — šlo o mylné pozorování. Cochrane přehledy uzavírají, že evidence pro prevenci ani léčbu chřipky je <b>nedostatečná</b>. Je také modelovým příkladem <a href="#gl-komplexni-homeopatie">indikačního</a>, nikoli individualizovaného předpisu.',see:['ch10']},
{k:'drenaz',t:'drenáž',alt:'drainage',d:'Postup zejména francouzské tradice: před nebo vedle hlubokého (konstitučního) léku se podávají nízké potence orgánově zaměřených léků, které mají „otevřít vylučovací cesty“ a zmírnit reakci. Patří k <a href="#gl-pluralismus">pluralismu</a> a v klasické unicistické praxi se nepoužívá, protože znemožňuje přiřadit reakci k jednomu léku (§ 273).',see:['ch1','ch5']},
{k:'antidotum',t:'antidotující lék',alt:'antidote',d:'Lék, který podle klinické tradice ruší nebo tlumí působení jiného homeopatického léku; užívá se při nadměrné aggravaci či nežádoucí reakci. Za tradičně univerzální antidot je považována <span class="rx">Camphora</span>, dále <span class="rx">Nux vomica</span>; <span class="rx">Coffea</span> ruší <span class="rx">Opium</span>. Do téže kategorie tradice řadí silné vůně, mentol a kafr. U vysokých potencí nelze mluvit o farmakologické interakci — jde o pojem uvnitř doktríny.',see:['ch6','ch7']},
{k:'ph-eur',t:'Evropský lékopis',alt:'Pharmacopoea Europaea, Ph. Eur.',d:'Právně závazný lékopis EU. Pro homeopatii obsahuje obecné monografie „Homoeopathic preparations“, „Mother tinctures for homoeopathic preparations“ a „Methods of preparation of homoeopathic stocks and potentisation“ a monografie jednotlivých surovin. Vedle něj se v praxi používá podrobnější německý <a href="#gl-hab">HAB</a>; v USA platí HPUS, ve Francii vlastní národní lékopis se značením CH a DH.',see:['ch7']},
{k:'gmp',t:'správná výrobní praxe (GMP)',alt:'good manufacturing practice',d:'Soubor požadavků na výrobu léčivých přípravků (dokumentace, kvalifikace zařízení, kontrola šarží, dohledatelnost), který platí <b>i pro homeopatika</b>. Dozor vykonává v ČR SÚKL. Praktický důsledek: kvalita a reprodukovatelnost <em>přípravy</em> homeopatik je doložitelná nezávisle na sporu o účinnost — a to je argument, který lze u zkoušky použít korektně.',see:['ch7']},
{k:'sukl',t:'SÚKL',alt:'Státní ústav pro kontrolu léčiv',d:'Český regulační orgán pro léčivé přípravky. Provádí registraci (u homeopatik nejčastěji ve <a href="#gl-zjednodusena-registrace">zjednodušeném režimu</a>), dozor nad výrobou a distribucí, farmakovigilanci a kontrolu reklamy. Registrace homeopatika v jeho databázi neznamená potvrzení účinnosti.',see:['ch7']},
{k:'cochrane',t:'Cochrane',alt:'Cochrane Collaboration',d:'Mezinárodní nezávislá síť zpracovávající systematické přehledy zdravotnických intervencí podle standardizované metodiky s explicitním hodnocením rizika zkreslení. Její přehledy homeopatie u jednotlivých indikací (<a href="#gl-oscillococcinum">Oscillococcinum</a> u chřipky, ADHD, astma, demence, indukce porodu) prakticky bez výjimky uzavírají, že evidence je nedostatečná. Pro zkoušku je to nejlepší zdroj, protože metodika je transparentní.',see:['ch10']},
{k:'organon-paragrafy',t:'paragrafy Organonu',alt:'§',d:'Organon je členěn na 291 číslovaných aforismů. Minimum, které má adept znát: <b>§ 1–2</b> cíl léčby, <b>§ 3</b> pracovní náplň lékaře, <b>§ 5</b> kauza a konstituce, <b>§ 6–7</b> symptomy a totalita, <b>§ 9–12</b> vitální síla a nemoc, <b>§ 18</b> individualizace, <b>§ 22, 26–29</b> zákon podobnosti, <b>§ 52–56</b> paliace, <b>§ 83–99</b> odběr případu, <b>§ 105–145</b> provingy, <b>§ 153</b> charakteristické symptomy, <b>§ 172–184</b> jednostranné případy, <b>§ 184–203</b> lokální nemoci a potlačení, <b>§ 246</b> opakování dávky, <b>§ 269–270</b> potenciace a LM, <b>§ 273</b> jediný lék, <b>§ 275–283</b> velikost dávky.',see:['ch1']}
];
